<?php
declare(strict_types=1);
final class ContentValidator{public static function data(array$i,string$t):array{$rules=['promotion'=>['title','slug'],'banner'=>['name'],'page'=>['title','slug'],'faq'=>['question','answer'],'testimonial'=>['author_name','quote'],'social'=>['platform','url']];foreach($rules[$t]??[] as$key)if(trim((string)($i[$key]??''))==='')throw new InvalidArgumentException('Falta completar: '.$key);if(in_array($t,['promotion','page'],true)){$slug=SlugService::make((string)($i['slug']??$i['title']));if($slug==='')throw new InvalidArgumentException('El slug no es válido.');$i['slug']=$slug;}if($t==='social'&&!filter_var($i['url']??'',FILTER_VALIDATE_URL))throw new InvalidArgumentException('La URL no es válida.');if($t==='testimonial'&&!empty($i['is_active'])&&empty($i['is_verified']))throw new InvalidArgumentException('Un testimonio debe verificarse antes de activarse.');return$i;}}
